void nvfs_crc_test_entry (NVFS_Entry * const nvfs_entry)
{
  if (nvfs_entry->crc != nvfs_crc_calc (& nvfs_entry->link , sizeof nvfs_entry->link))
    {
      NvfsThrow NVFS_ERROR ;
    }
}

